using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;

namespace SecureVault
{
    public class VaultEntry
    {
        public string EntryId { get; set; }
        public string OwnerId { get; set; }
        public string EncryptedPayload { get; set; }
        public string Nonce { get; set; }
        public string Tag { get; set; }
    }

    public class VaultIndex
    {
        public VaultEntry[] Entries { get; set; } = Array.Empty<VaultEntry>();
    }

    public static class CryptoHelper
    {
        public static byte[] DeriveKey(string password, byte[] salt)
        {
            using var pbkdf2 = new Rfc2898DeriveBytes(password, salt, 100000, HashAlgorithmName.SHA256);
            return pbkdf2.GetBytes(32);
        }

        public static (byte[] ciphertext, byte[] nonce, byte[] tag) Encrypt(byte[] plaintext, byte[] key)
        {
            byte[] nonce = new byte[12];
            RandomNumberGenerator.Fill(nonce);
            byte[] ciphertext = new byte[plaintext.Length];
            byte[] tag = new byte[16];
            using var aes = new AesGcm(key, 16);
            aes.Encrypt(nonce, plaintext, ciphertext, tag);
            return (ciphertext, nonce, tag);
        }

        public static byte[] Decrypt(byte[] ciphertext, byte[] key, byte[] nonce, byte[] tag)
        {
            byte[] plaintext = new byte[ciphertext.Length];
            using var aes = new AesGcm(key, 16);
            aes.Decrypt(nonce, ciphertext, tag, plaintext);
            return plaintext;
        }
    }

    public class AccessControl
    {
        private readonly string _currentUserId;
        private readonly string _vaultPath;

        public AccessControl(string currentUserId, string vaultPath)
        {
            _currentUserId = currentUserId;
            _vaultPath = vaultPath;
        }

        public bool ValidateOwnership(string entryId)
        {
            var index = LoadIndex();
            var entry = FindEntry(index, entryId);
            if (entry == null) return false;
            return CheckOwner(entry);
        }

        private VaultIndex LoadIndex()
        {
            string indexPath = Path.Combine(_vaultPath, "index.json");
            string json = File.ReadAllText(indexPath);
            return JsonSerializer.Deserialize<VaultIndex>(json);
        }

        private VaultEntry FindEntry(VaultIndex index, string entryId)
        {
            foreach (var entry in index.Entries)
            {
                if (entry.EntryId == entryId)
                    return entry;
            }
            return null;
        }

        private bool CheckOwner(VaultEntry entry)
        {
            // Ownership verified by comparing stored owner with session user
            return string.Equals(entry.OwnerId, _currentUserId, StringComparison.Ordinal);
        }
    }

    public class VaultService
    {
        private readonly string _vaultPath;
        private readonly byte[] _masterKey;
        private readonly AccessControl _acl;
        private readonly string _userId;

        public VaultService(string userId, string password, string vaultPath)
        {
            _userId = userId;
            _vaultPath = vaultPath;
            byte[] salt = LoadOrCreateSalt();
            _masterKey = CryptoHelper.DeriveKey(password, salt);
            _acl = new AccessControl(userId, vaultPath);
        }

        private byte[] LoadOrCreateSalt()
        {
            string saltPath = Path.Combine(_vaultPath, "salt.bin");
            if (File.Exists(saltPath))
                return File.ReadAllBytes(saltPath);
            byte[] salt = new byte[16];
            RandomNumberGenerator.Fill(salt);
            Directory.CreateDirectory(_vaultPath);
            File.WriteAllBytes(saltPath, salt);
            return salt;
        }

        public string RetrieveEntry(string entryId)
        {
            // Perform access control check first
            bool authorized = _acl.ValidateOwnership(entryId);
            if (!authorized)
                throw new UnauthorizedAccessException("Access denied");

            // Only load and decrypt after authorization confirmed
            string entryPath = ResolveEntryPath(entryId);
            if (!File.Exists(entryPath))
                throw new FileNotFoundException("Entry not found");

            var entry = LoadEntryMetadata(entryId);
            byte[] ciphertext = File.ReadAllBytes(entryPath);
            byte[] nonce = Convert.FromBase64String(entry.Nonce);
            byte[] tag = Convert.FromBase64String(entry.Tag);

            byte[] plaintext = CryptoHelper.Decrypt(ciphertext, _masterKey, nonce, tag);
            return Encoding.UTF8.GetString(plaintext);
        }

        public string RetrieveEntryByOffset(int offset)
        {
            // Retrieve entry by user's entry offset (0 = first entry, 1 = second, etc.)
            var index = LoadIndex();
            int userEntryCount = 0;
            foreach (var entry in index.Entries)
            {
                if (entry.OwnerId == _userId)
                {
                    if (userEntryCount == offset)
                        return RetrieveEntry(entry.EntryId);
                    userEntryCount++;
                }
            }
            throw new ArgumentException("Entry offset out of range");
        }

        public string RetrieveSharedEntry(string entryId, string sharedByUserId)
        {
            // For shared entries, we check if the sharing user owns it
            // and if current user is in the share list
            var entry = LoadEntryMetadata(entryId);
            if (entry == null)
                throw new FileNotFoundException("Entry not found");

            // Verify the entry belongs to the claimed sharing user
            if (!string.Equals(entry.OwnerId, sharedByUserId, StringComparison.Ordinal))
                throw new UnauthorizedAccessException("Invalid share source");

            // Check share permissions from share manifest
            string sharePath = Path.Combine(_vaultPath, "shares", $"{Path.GetFileName(entryId)}.json");
            if (!File.Exists(sharePath))
                throw new UnauthorizedAccessException("No share record found");

            string shareJson = File.ReadAllText(sharePath);
            var shareList = JsonSerializer.Deserialize<string[]>(shareJson);

            bool isSharedWithUser = false;
            foreach (var uid in shareList)
            {
                if (string.Equals(uid, _userId, StringComparison.Ordinal))
                {
                    isSharedWithUser = true;
                    break;
                }
            }

            if (!isSharedWithUser)
                throw new UnauthorizedAccessException("Entry not shared with you");

            // Authorized - decrypt and return
            string entryPath = ResolveEntryPath(entryId);
            byte[] ciphertext = File.ReadAllBytes(entryPath);
            byte[] nonce = Convert.FromBase64String(entry.Nonce);
            byte[] tag = Convert.FromBase64String(entry.Tag);
            byte[] plaintext = CryptoHelper.Decrypt(ciphertext, _masterKey, nonce, tag);
            return Encoding.UTF8.GetString(plaintext);
        }

        private string ResolveEntryPath(string entryId)
        {
            // Sanitize entryId to prevent path traversal
            string sanitized = Path.GetFileName(entryId);
            return Path.Combine(_vaultPath, "entries", sanitized + ".enc");
        }

        private VaultEntry LoadEntryMetadata(string entryId)
        {
            var index = LoadIndex();
            foreach (var entry in index.Entries)
            {
                if (entry.EntryId == entryId)
                    return entry;
            }
            return null;
        }

        private VaultIndex LoadIndex()
        {
            string indexPath = Path.Combine(_vaultPath, "index.json");
            string json = File.ReadAllText(indexPath);
            return JsonSerializer.Deserialize<VaultIndex>(json);
        }
    }

    class Program
    {
        static void Main(string[] args)
        {
            if (args.Length < 4)
            {
                Console.WriteLine("Usage: vault <userId> <password> <command> <args...>");
                return;
            }

            string userId = args[0];
            string password = args[1];
            string command = args[2];
            string vaultPath = Environment.GetEnvironmentVariable("VAULT_PATH") ?? "./vault_data";

            var service = new VaultService(userId, password, vaultPath);

            switch (command)
            {
                case "get":
                    Console.WriteLine(service.RetrieveEntry(args[3]));
                    break;
                case "get-by-index":
                    Console.WriteLine(service.RetrieveEntryByOffset(int.Parse(args[3])));
                    break;
                case "get-shared":
                    Console.WriteLine(service.RetrieveSharedEntry(args[3], args[4]));
                    break;
                default:
                    Console.WriteLine("Unknown command");
                    break;
            }
        }
    }
}
